/**
 * Bridge for RelicModal — relic grid in Svelte ({@html}), not relicOptionsGrid.innerHTML.
 */

import { awaitLazyModalReady } from '../lib/lazyModalMounts.ts';

export type RelicModalPayload = {
  bodyLabel: string;
  gridHtml: string;
  /** Pilote auto actif : pas de blur ni capture des clics hors panneau. */
  passive?: boolean;
};

type ShowFn = (payload: RelicModalPayload) => void;
type CloseFn = () => void;

let _show: ShowFn | null = null;
let _close: CloseFn | null = null;
let _pendingPayload: RelicModalPayload | null = null;
let _pendingPaintedWait: (() => void) | null = null;

export function setRelicModalShow(fn: ShowFn): void {
  _show = fn;
  if (_pendingPayload) {
    const payload = _pendingPayload;
    _pendingPayload = null;
    fn(payload);
    if (_pendingPaintedWait) {
      const resolve = _pendingPaintedWait;
      _pendingPaintedWait = null;
      void whenRelicModalPainted().then(resolve);
    }
  }
}
export function setRelicModalClose(fn: CloseFn): void { _close = fn; }

export async function showRelicModal(payload: RelicModalPayload): Promise<void> {
  await awaitLazyModalReady('relicModal');
  if (_show) _show(payload);
  else _pendingPayload = payload;
}

/** After Svelte {@html} has painted (two animation frames). */
export function whenRelicModalPainted(): Promise<void> {
  return new Promise((resolve) => {
    if (typeof requestAnimationFrame === 'function') {
      requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
    } else {
      resolve();
    }
  });
}

export async function showRelicModalWhenPainted(payload: RelicModalPayload): Promise<void> {
  await awaitLazyModalReady('relicModal');
  if (_show) {
    _show(payload);
    await Promise.resolve();
    await whenRelicModalPainted();
    return;
  }
  _pendingPayload = payload;
  await new Promise<void>((resolve) => {
    _pendingPaintedWait = resolve;
  });
}

export function closeRelicModal(): void {
  _close?.();
}

if (typeof globalThis !== 'undefined') {
  (globalThis as Record<string, unknown>).__showRelicModal = showRelicModal;
  (globalThis as Record<string, unknown>).__showRelicModalWhenPainted = showRelicModalWhenPainted;
  (globalThis as Record<string, unknown>).__closeRelicModal = closeRelicModal;
}
